// Accepts three shapes: IMAP email (resolved), webhook {from_email, from_name, subject, body, message_id}, or an
// Execute Workflow call with the same fields. Output is one clean message plus a skip flag for anything automated.
const j = $input.item.json || {};
const wb = (j.body && typeof j.body === 'object') ? j.body : null;
const direct = wb && (wb.from_email || wb.body) ? wb : (j.from_email ? j : null);
let source, fromEmail, fromName, subject, text, html, messageId, headers = {};
if (direct) {
  source = wb ? 'webhook' : 'workflow';
  fromEmail = direct.from_email; fromName = direct.from_name; subject = direct.subject; text = direct.body || direct.text || ''; html = direct.html || '';
  messageId = direct.message_id || '';
} else {
  source = 'imap';
  const f = (j.from && j.from.value && j.from.value[0]) || {};
  fromEmail = f.address || (typeof j.from === 'string' ? j.from : ''); fromName = f.name || '';
  subject = j.subject || ''; text = j.text || j.textPlain || ''; html = j.html || j.textHtml || ''; messageId = j.messageId || (j.headers && j.headers['message-id']) || '';
  headers = j.headers || {};
}
fromEmail = String(fromEmail || '').trim().toLowerCase();
const m = fromEmail.match(/<([^>]+)>/); if (m) fromEmail = m[1].trim();
subject = String(subject || '').replace(/\s+/g, ' ').trim().slice(0, 250);
if (!text && html) text = String(html).replace(/<style[\s\S]*?<\/style>|<script[\s\S]*?<\/script>/gi, ' ').replace(/<br\s*\/?>|<\/(p|div|li|tr|h\d)>/gi, '\n').replace(/<[^>]+>/g, ' ').replace(/&nbsp;/g, ' ').replace(/&amp;/g, '&').replace(/&lt;/g, '<').replace(/&gt;/g, '>').replace(/&#39;/g, "'").replace(/&quot;/g, '"');
// Drop quoted history and signatures-after-quote so the model only reads what the sender just wrote.
const lines = String(text || '').replace(/\r/g, '').split('\n'); const kept = [];
for (const ln of lines) {
  if (/^\s*>/.test(ln) || /^On .{5,120} wrote:\s*$/i.test(ln) || /^-{2,}\s*(Original Message|Forwarded message)/i.test(ln) || /^From:\s.+@/i.test(ln)) break;
  kept.push(ln);
}
const body = kept.join('\n').replace(/[ \t]+/g, ' ').replace(/\n{3,}/g, '\n\n').trim().slice(0, 3500);
const hv = (k) => String(headers[k] || '').toLowerCase();
const OWN = ['gilbeydulnuan@gmail.com', 'gilbeydulnuan@gmail.com'];
let skipReason = '';
if (!/^[^@\s]+@[^@\s]+\.[^@\s]+$/.test(fromEmail)) skipReason = 'no valid sender address';
else if (OWN.includes(fromEmail)) skipReason = 'sent from our own address';
else if (body.length < 5) skipReason = 'empty message';
else if (source === 'imap') {
  if (/(^|[._-])(no-?reply|donotreply|do-not-reply|mailer-daemon|postmaster|bounce|bounces|notifications?|newsletter|news|marketing|alerts?)([._-]|@)/.test(fromEmail)) skipReason = 'automated sender';
  else if (headers['list-unsubscribe'] || /bulk|list|junk/.test(hv('precedence')) || (hv('auto-submitted') && hv('auto-submitted') !== 'no') || headers['x-autoreply'] || headers['x-autorespond']) skipReason = 'bulk or automatic email';
}
function hash(s) { let h = 5381; for (let i = 0; i < s.length; i++) h = ((h << 5) + h + s.charCodeAt(i)) | 0; return (h >>> 0).toString(36); }
if (!messageId) messageId = 'gen-' + hash(fromEmail + '|' + subject + '|' + body);
return { json: { skip: !!skipReason, skipReason, source, fromEmail, fromName: String(fromName || '').trim().slice(0, 120), subject, body, messageId: String(messageId).slice(0, 300), contactId: direct && direct.contact_id ? Number(direct.contact_id) : null } };

const m = $('Normalize Input').item.json;
let model = 'qwen2.5:3b';
try { model = $env.INTAKE_OLLAMA_MODEL || model; } catch (e) {}
const system = [
  'You triage inbound emails for a roofing / home-service company. Read the email and answer with ONE JSON object only, no other text.',
  'Fields:',
  '"intent": one of "lead" (wants a quote, inspection, repair or new work), "support" (existing customer problem, warranty, billing, scheduling), "spam" (sales pitch, marketing, phishing, automated), "other".',
  '"intent_score": integer 0-100, how likely this person wants to hire us or needs our help now.',
  '"service_type": one of "roof_repair","roof_replacement","inspection","storm_damage","gutters","other","none".',
  '"urgency": one of "emergency" (active leak, storm damage, safety, needs help today), "high" (within days), "normal", "low".',
  '"name": the sender\'s full name or null. "phone": phone number or null. "zip_code": 5-digit US ZIP or null. "budget": number in dollars or null.',
  '"sentiment": "angry","neutral" or "positive". "summary": one sentence, max 25 words, what they need.',
  'Use null for anything not stated. Never invent values.'
].join('\n');
const user = 'From: ' + (m.fromName ? m.fromName + ' <' + m.fromEmail + '>' : m.fromEmail) + '\nSubject: ' + m.subject + '\n\n' + m.body;
return { json: { ollamaBody: { model, stream: false, format: 'json', keep_alive: '10m', options: { temperature: 0, num_ctx: 4096, num_predict: 300 }, messages: [{ role: 'system', content: system }, { role: 'user', content: user }] } } };

// Validate + normalize the model's answer. If Ollama is down or answers badly, a rule-based fallback fills every field,
// so an inbound lead is never dropped just because the AI failed.
const m = $('Normalize Input').item.json;
const resp = $input.item.json || {};
let ai = null, aiUsed = false, aiError = '';
try {
  const content = resp.message && resp.message.content;
  if (content) { ai = JSON.parse(String(content).replace(/^```(?:json)?|```$/g, '').trim()); aiUsed = !!ai && typeof ai === 'object'; }
  else aiError = String((resp.error && (resp.error.message || resp.error)) || 'no response from Ollama').slice(0, 200);
} catch (e) { aiError = 'unreadable AI answer'; ai = null; }
ai = ai || {};
const text = (m.subject + '\n' + m.body);
const low = text.toLowerCase();
const pick = (v, allowed, dflt) => { const s = String(v == null ? '' : v).toLowerCase().trim().replace(/[\s-]+/g, '_'); return allowed.includes(s) ? s : dflt; };

// --- fallback / cross-check signals (regex over the raw text) ---
const EMERG = /\b(leak(?:ing|s)?|water (?:coming|pouring|dripping)|storm damage|hail|tree (?:fell|on)|fallen tree|collapse[d]?|emergency|asap|right away|immediately|urgent(?:ly)?|today|tonight|tarp|flood(?:ed|ing)?)\b/g;
const ROOFY = /\b(roof|roofing|shingle|gutter|leak|inspection|estimate|quote|storm|hail|siding|repair|replace(?:ment)?|insurance claim)\b/;
const emergHits = (low.match(EMERG) || []).length;
const zipMatch = text.match(/\b(\d{5})(?:-\d{4})?\b/);
const phoneMatch = text.match(/(?:\+?1[\s.\-]?)?\(?(\d{3})\)?[\s.\-]?(\d{3})[\s.\-]?(\d{4})\b/);
let budgetFound = null;
const bm = text.match(/\$\s?(\d[\d,]*(?:\.\d+)?)\s?(k|K|grand)?/) || text.match(/\b(\d[\d,]*)\s?(k|K)\b\s*(?:budget|\$)?/);
if (bm) { let n = parseFloat(bm[1].replace(/,/g, '')); if (bm[2]) n *= 1000; if (isFinite(n) && n > 0 && n < 10000000) budgetFound = Math.round(n); }

// --- normalize each field ---
let intent = pick(ai.intent, ['lead', 'support', 'spam', 'other'], '');
if (!intent) intent = ROOFY.test(low) ? 'lead' : 'other';
let intentScore = Math.round(Number(ai.intent_score));
if (!isFinite(intentScore)) intentScore = intent === 'lead' ? (emergHits ? 80 : 55) : intent === 'support' ? 50 : 10;
intentScore = Math.max(0, Math.min(100, intentScore));
const service = pick(ai.service_type, ['roof_repair', 'roof_replacement', 'inspection', 'storm_damage', 'gutters', 'other', 'none'],
  /storm|hail/.test(low) ? 'storm_damage' : /leak|repair/.test(low) ? 'roof_repair' : /replace|new roof/.test(low) ? 'roof_replacement' : /inspect|estimate|quote/.test(low) ? 'inspection' : /gutter/.test(low) ? 'gutters' : (ROOFY.test(low) ? 'other' : 'none'));
let urgency = pick(ai.urgency, ['emergency', 'high', 'normal', 'low'], '');
if (!urgency) urgency = emergHits >= 2 ? 'emergency' : emergHits === 1 ? 'high' : 'normal';
// Never let the model downplay an obvious emergency.
if (urgency !== 'emergency' && /\b(leak(?:ing)?|storm damage|fallen tree|tree (?:fell|on)|collapse[d]?)\b/.test(low) && /\b(today|tonight|now|asap|immediately|right away)\b/.test(low)) urgency = 'emergency';
let zip = String(ai.zip_code == null ? '' : ai.zip_code).match(/\d{5}/); zip = zip ? zip[0] : (zipMatch ? zipMatch[1] : '');
let phoneRaw = String(ai.phone || '') || (phoneMatch ? phoneMatch[0] : '');
const pd = phoneRaw.replace(/\D/g, ''); const p10 = pd.length === 11 && pd[0] === '1' ? pd.slice(1) : pd;
const phone = p10.length === 10 ? '(' + p10.slice(0, 3) + ') ' + p10.slice(3, 6) + '-' + p10.slice(6) : '';
let budget = ai.budget != null && ai.budget !== '' ? Number(String(ai.budget).replace(/[^0-9.]/g, '')) : null;
if (!isFinite(budget) || budget <= 0) budget = budgetFound;
const sentiment = pick(ai.sentiment, ['angry', 'neutral', 'positive'], 'neutral');
const tc = (s) => String(s || '').toLowerCase().split(/\s+/).filter(Boolean).map((w) => w[0].toUpperCase() + w.slice(1)).join(' ');
let name = String(ai.name || '').replace(/[^\p{L}\p{M}'\-. ]/gu, '').trim() || String(m.fromName || '').replace(/[^\p{L}\p{M}'\-. ]/gu, '').trim();
if (!name) name = tc(m.fromEmail.split('@')[0].replace(/[._\-0-9]+/g, ' ').trim());
name = tc(name).slice(0, 100) || 'Unknown';
const parts = name.split(' '); const firstName = parts[0] || 'Unknown'; const lastName = parts.slice(1).join(' ');
let summary = String(ai.summary || '').replace(/\s+/g, ' ').trim().slice(0, 300);
if (!summary) summary = (m.subject || m.body).replace(/\s+/g, ' ').slice(0, 160);

// --- priority score 0-100 (deterministic, so the same email always scores the same) ---
const base = { emergency: 60, high: 40, normal: 20, low: 5 }[urgency];
let score = base + Math.round(intentScore * 0.25) + Math.min(15, emergHits * 5) + (zip && phone ? 5 : 0) + (budget && budget >= 5000 ? 5 : 0) + (sentiment === 'angry' ? 5 : 0);
if (intent === 'spam') score = Math.min(score, 10);
score = Math.max(0, Math.min(100, score));
const createTicket = (intent === 'lead' || intent === 'support') && intentScore >= 20;
return { json: { aiUsed, aiError, intent, intentScore, service, urgency, zip, phone, budget: budget || null, sentiment, name, firstName, lastName, summary, priorityScore: score, createTicket, emergHits } };

// Combine the AI result with the service-area check into the final priority, then build every value the DB steps need.
const m = $('Normalize Input').item.json;
const r = $('Validate & Normalize').item.json;
const area = $input.item.json || {};
const configured = Number(area.configured || 0) > 0;
const inArea = !!area.in_area;
const areaStatus = !r.zip ? 'unknown' : !configured ? 'not configured' : inArea ? 'eligible' : 'outside service area';
let priority = r.priorityScore >= 70 ? 'urgent' : r.priorityScore >= 50 ? 'high' : r.priorityScore >= 28 ? 'normal' : 'low';
// A confirmed out-of-area request is still logged, but it must not page the team as urgent.
if (areaStatus === 'outside service area' && (priority === 'urgent' || priority === 'high')) priority = 'normal';
const SLA = { urgent: 4, high: 8, normal: 24, low: 72 };
const LBL = { roof_repair: 'Roof repair', roof_replacement: 'Roof replacement', inspection: 'Inspection', storm_damage: 'Storm damage', gutters: 'Gutters', other: 'Other', none: 'General inquiry' };
const service = LBL[r.service];
const urgencyLbl = r.urgency[0].toUpperCase() + r.urgency.slice(1);
const prLbl = priority[0].toUpperCase() + priority.slice(1);
const category = r.intent === 'support' ? 'Support' : 'Lead Inquiry';
const subject = ((priority === 'urgent' ? '[URGENT] ' : '') + service + ' - ' + r.name + (r.zip ? ' - ' + r.zip : '')).slice(0, 240);
const money = r.budget ? '$' + Number(r.budget).toLocaleString('en-US') : 'Unknown';
const description = [
  'AI summary: ' + r.summary + (r.aiUsed ? '' : '  (AI unavailable - rule-based triage)'),
  '',
  'Service: ' + service + '  |  Urgency: ' + urgencyLbl + '  |  Priority: ' + prLbl + ' (score ' + r.priorityScore + ')',
  'Intent: ' + r.intent + ' (' + r.intentScore + '/100)  |  Sentiment: ' + r.sentiment,
  'ZIP: ' + (r.zip || 'not given') + ' (service area: ' + areaStatus + ')  |  Budget: ' + money,
  'Contact: ' + r.name + ' - ' + m.fromEmail + (r.phone ? ' - ' + r.phone : ''),
  'Source: email "' + m.subject + '"',
  '',
  '--- Original message ---',
  m.body
].join('\n');
const tags = ['ai-intake'];
if (priority === 'urgent') tags.push('urgent lead');
if (areaStatus === 'outside service area') tags.push('out of area');
const result = { intent: r.intent, intent_score: r.intentScore, service: r.service, urgency: r.urgency, zip: r.zip, phone: r.phone, budget: r.budget, area: areaStatus, priority, priority_score: r.priorityScore, ai_used: r.aiUsed, ai_error: r.aiError, summary: r.summary };
return { json: { ...r, priority, areaStatus, slaHours: SLA[priority], category, subject, description, tags, result, fromEmail: m.fromEmail, messageId: m.messageId, emailSubject: m.subject, emailBody: m.body, service: service, serviceKey: r.service } };

