WITH existing AS (
  SELECT id, owner_id FROM contacts WHERE lower(email) = lower($1) AND is_archived = false ORDER BY id LIMIT 1
), owner AS (
  SELECT COALESCE(
    (SELECT u.id FROM users u LEFT JOIN contacts c2 ON c2.owner_id = u.id AND c2.is_archived = false WHERE u.role = 'user' AND u.active = true GROUP BY u.id ORDER BY COUNT(c2.id) ASC, u.id ASC LIMIT 1),
    (SELECT id FROM users WHERE role = 'admin' AND active = true ORDER BY id LIMIT 1)
  ) AS id
), ins AS (
  INSERT INTO contacts (first_name, last_name, email, phone, zip_code, lead_status, lead_source, lead_score, owner_id, created_at, updated_at)
  SELECT $2, NULLIF($3, ''), $1, NULLIF($4, ''), NULLIF($5, ''), 'New', 'Email (AI Intake)', $6::int, (SELECT id FROM owner), now(), now()
  WHERE NOT EXISTS (SELECT 1 FROM existing)
  RETURNING id, owner_id
), upd AS (
  UPDATE contacts SET owner_id = COALESCE(owner_id, (SELECT id FROM owner)), phone = COALESCE(NULLIF(phone, ''), NULLIF($4, '')), updated_at = now()
  WHERE id = (SELECT id FROM existing) RETURNING id, owner_id
)
SELECT id, owner_id, true AS is_new FROM ins UNION ALL SELECT id, owner_id, false AS is_new FROM upd;

WITH t AS (
  INSERT INTO tickets (subject, description, priority, status, category, contact_id, assigned_user, sla_due_at, submitter_name, submitter_email, source)
  VALUES ($1, $2, $3, 'open', $4, $5::int, $6::int, now() + ($7 || ' hours')::interval, $8, $9, 'ai_intake') RETURNING id
), lg AS (
  INSERT INTO entity_activity_log (entity_type, entity_id, category, subtype, summary, actor_id, actor_name)
  SELECT 'ticket', id, 'ticket', 'created', $10, NULL, 'AI Intake' FROM t
), up AS (
  UPDATE ai_intake_log SET status = 'ticket_created', contact_id = $5::int, ticket_id = (SELECT id FROM t), result = $11::jsonb WHERE message_id = $12
), tg AS (
  INSERT INTO tags (name) SELECT jsonb_array_elements_text($13::jsonb) ON CONFLICT (name) DO UPDATE SET name = EXCLUDED.name RETURNING id
), tgl AS (
  INSERT INTO taggables (tag_id, entity_type, entity_id) SELECT id, 'contact', $5::int FROM tg ON CONFLICT (tag_id, entity_type, entity_id) DO NOTHING
), el AS (
  UPDATE contacts SET email_logs = COALESCE(email_logs, '[]'::jsonb) || jsonb_build_object('id', gen_random_uuid()::text, 'type', 'received', 'subject', $14::text, 'message', $15::text, 'attachments', '[]'::jsonb, 'sent_at', now(), 'is_read', false) WHERE id = $5::int
)
SELECT id FROM t;

