// Direct message to the owner (user 1 sends, unless user 1 IS the owner: then the system sender, so it counts as unread).
const f = $('Finalize').item.json;
const c = $('Upsert Contact').item.json;
const t = $('Create Ticket').item.json;
const BOT = 9;
const ownerId = c.owner_id != null ? Number(c.owner_id) : 1;
const notifier = ownerId === 1 ? BOT : 1;
let base = ''; try { base = $env.FRONTEND_BASE_URL || ''; } catch (e) {}
const icon = f.priority === 'urgent' ? '🚨 URGENT' : f.priority === 'high' ? '🔥 High priority' : 'New';
const text = [
  icon + ' ' + (c.is_new ? 'lead' : 'message') + ' - ' + f.name + (f.zip ? ' (ZIP ' + f.zip + ')' : ''),
  f.service + ' - ' + f.urgency + ' - priority ' + f.priority + ' (' + f.priorityScore + '), intent ' + f.intentScore + '/100',
  '"' + f.summary + '"',
  [f.phone, f.fromEmail].filter(Boolean).join(' - ') + ' - service area: ' + f.areaStatus,
  'Ticket #' + t.id + (base ? ': ' + base + '/tickets/' + t.id : '')
].join('\n');
return { json: { ownerId, notifier, dmKey: [notifier, ownerId].sort((a, b) => a - b).join('-'), text, bypassPrefs: f.priority === 'urgent' } };

// One item per recipient (the ticket owner and every active admin) for tickets nobody acknowledged within 5 minutes.
const j = $input.item.json;
const BOT = 9; const rid = Number(j.recipient_id);
let base = ''; try { base = $env.FRONTEND_BASE_URL || ''; } catch (e) {}
const text = '⏰ ESCALATION - urgent ticket #' + j.ticket_id + ' has not been acknowledged in 5 minutes.\n' + j.subject + (base ? '\n' + base + '/tickets/' + j.ticket_id : '');
return { json: { ownerId: rid, notifier: BOT, dmKey: [BOT, rid].sort((a, b) => a - b).join('-'), text, bypassPrefs: true } };
